from solution import game_score

def test_empty():
    assert game_score('') == '0-0'

def test_example():
    assert game_score('AAB') == '30-15'

def test_deuce():
    assert game_score('AAABBB') == '40-40'

def test_deuce_a_wins():
    assert game_score('AAABBBA') == 'Game A'

def test_deuce_b_wins():
    assert game_score('AAABBBB') == 'Game B'

def test_ignore_after_win():
    assert game_score('AAAAB') == 'Game A'
    assert game_score('BBBBAAAA') == 'Game B'

def test_ignore_after_deuce_win():
    assert game_score('AAABBBAB') == 'Game A'
    assert game_score('AAABBBBA') == 'Game B'

def test_40_15():
    assert game_score('AAAB') == '40-15'

def test_15_40():
    assert game_score('ABBB') == '15-40'

def test_40_30():
    assert game_score('AABBA') == '40-30'

def test_win_with_opponent_30():
    assert game_score('AABBAA') == 'Game A'

def test_love_game_b():
    assert game_score('BBBB') == 'Game B'

def test_single():
    assert game_score('A') == '15-0'
    assert game_score('B') == '0-15'

def test_reach_deuce_alternating():
    assert game_score('ABABAB') == '40-40'
